def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max({v for row in g for v in row}, key=lambda v: sum(row.count(v) for row in g))
    for y0 in range(h):
        for y1 in range(y0 + 2, h):
            for x0 in range(w):
                for x1 in range(x0 + 2, w):
                    color = g[y0][x0]
                    if color == bg:
                        continue
                    if any(g[y0][x] != color or g[y1][x] != color for x in range(x0, x1 + 1)):
                        continue
                    if any(g[y][x0] != color or g[y][x1] != color for y in range(y0, y1 + 1)):
                        continue
                    if any(g[y][x] != bg for y in range(y0 + 1, y1) for x in range(x0 + 1, x1)):
                        continue
                    area = (y1 - y0 - 1) * (x1 - x0 - 1)
                    fill = 7 if area % 2 else 2
                    for y in range(y0 + 1, y1):
                        for x in range(x0 + 1, x1):
                            g[y][x] = fill
    return g
